## Goal
Create a new analyzer that collects ALL variable usages in a single O(n) pass.

## Implementation
```haxe
class OptimizedVarUseAnalyzer {
    // Single pass: collect ALL variable references → O(n)
    public static function collectAllUsages(stmts: Array<ElixirAST>): Map<String, Array<Int>> {
        var usages = new Map<String, Array<Int>>();
        for (i in 0...stmts.length) {
            walkCollect(stmts[i], i, usages);
        }
        return usages;
    }

    // Check if used after index → O(1)
    public static function isUsedAfter(usages: Map<String, Array<Int>>, name: String, afterIndex: Int): Bool {
        var indices = usages.get(name);
        if (indices == null) return false;
        return indices.exists(idx -> idx > afterIndex);
    }
}
```

